INSERT INTO "recommendation_offers" (
  "product_id", "retailer_name", "affiliate_program", "destination_url",
  "regions", "currency", "price_label", "priority", "active",
  "last_checked_at", "last_http_status"
)
SELECT
  p."id", v."retailer_name", v."affiliate_program",
  v."destination_url", v."regions"::jsonb, v."currency",
  v."price_label", 0, true, now(), 200
FROM (
  VALUES
    ('maap-training-jersey-2', 'MAAP', 'MAAP Cycling Apparel — Impact', 'https://maap.sjv.io/Ag027D?subId1=roadman-recommends&subId2=maap-training-jersey-2&u=https%3A%2F%2Fmaap.cc%2Fproducts%2Ftraining-jersey-2-0-thistle', '["IE","GB","EU","US"]', 'EUR', 'View current price'),
    ('maap-spectrum-pro-air-jersey-3', 'MAAP', 'MAAP Cycling Apparel — Impact', 'https://maap.sjv.io/Ag027D?subId1=roadman-recommends&subId2=maap-spectrum-pro-air-jersey-3&u=https%3A%2F%2Fmaap.cc%2Fproducts%2Fspectrum-pro-air-jersey-3-0-mirage', '["IE","GB","EU","US"]', 'EUR', 'View current price'),
    ('maap-alt-road-jersey-2', 'MAAP', 'MAAP Cycling Apparel — Impact', 'https://maap.sjv.io/Ag027D?subId1=roadman-recommends&subId2=maap-alt-road-jersey-2&u=https%3A%2F%2Fmaap.cc%2Fproducts%2Falt_road-jersey-2-0-bijou-blue', '["IE","GB","EU","US"]', 'EUR', 'View current price'),
    ('maap-training-bib-3', 'MAAP', 'MAAP Cycling Apparel — Impact', 'https://maap.sjv.io/Ag027D?subId1=roadman-recommends&subId2=maap-training-bib-3&u=https%3A%2F%2Fmaap.cc%2Fproducts%2Ftraining-bib-3-0-cobblestone', '["IE","GB","EU","US"]', 'EUR', 'View current price'),
    ('maap-alt-road-cargo-bib-2', 'MAAP', 'MAAP Cycling Apparel — Impact', 'https://maap.sjv.io/Ag027D?subId1=roadman-recommends&subId2=maap-alt-road-cargo-bib-2&u=https%3A%2F%2Fmaap.cc%2Fproducts%2Falt_road-cargo-bib-2-0-deep-navy', '["IE","GB","EU","US"]', 'EUR', 'View current price'),
    ('maap-team-bib-evo-cargo', 'MAAP', 'MAAP Cycling Apparel — Impact', 'https://maap.sjv.io/Ag027D?subId1=roadman-recommends&subId2=maap-team-bib-evo-cargo&u=https%3A%2F%2Fmaap.cc%2Fproducts%2Fteam-bib-evo-cargo-deep-navy', '["IE","GB","EU","US"]', 'EUR', 'View current price'),
    ('womens-maap-training-jersey-2', 'MAAP', 'MAAP Cycling Apparel — Impact', 'https://maap.sjv.io/Ag027D?subId1=roadman-recommends&subId2=womens-maap-training-jersey-2&u=https%3A%2F%2Fmaap.cc%2Fproducts%2Fwomens-training-jersey-2-0-washed-red', '["IE","GB","EU","US"]', 'EUR', 'View current price'),
    ('womens-maap-team-bib-evo', 'MAAP', 'MAAP Cycling Apparel — Impact', 'https://maap.sjv.io/Ag027D?subId1=roadman-recommends&subId2=womens-maap-team-bib-evo&u=https%3A%2F%2Fmaap.cc%2Fproducts%2Fwomens-team-bib-evo-titanium', '["IE","GB","EU","US"]', 'EUR', 'View current price'),
    ('maap-atmos-vest', 'MAAP', 'MAAP Cycling Apparel — Impact', 'https://maap.sjv.io/Ag027D?subId1=roadman-recommends&subId2=maap-atmos-vest&u=https%3A%2F%2Fmaap.cc%2Fproducts%2Fatmos-vest-black', '["IE","GB","EU","US"]', 'EUR', 'View current price'),
    ('maap-elements-pro-race-jacket', 'MAAP', 'MAAP Cycling Apparel — Impact', 'https://maap.sjv.io/Ag027D?subId1=roadman-recommends&subId2=maap-elements-pro-race-jacket&u=https%3A%2F%2Fmaap.cc%2Fproducts%2Felements-pro-race-jacket-black', '["IE","GB","EU","US"]', 'EUR', 'View current price'),
    ('maap-team-mesh-base-layer', 'MAAP', 'MAAP Cycling Apparel — Impact', 'https://maap.sjv.io/Ag027D?subId1=roadman-recommends&subId2=maap-team-mesh-base-layer&u=https%3A%2F%2Fmaap.cc%2Fproducts%2Fteam-mesh-base-layer-white', '["IE","GB","EU","US"]', 'EUR', 'View current price'),
    ('maap-spectrum-team-sock', 'MAAP', 'MAAP Cycling Apparel — Impact', 'https://maap.sjv.io/Ag027D?subId1=roadman-recommends&subId2=maap-spectrum-team-sock&u=https%3A%2F%2Fmaap.cc%2Fproducts%2Fspectrum-team-sock-black', '["IE","GB","EU","US"]', 'EUR', 'View current price')
) AS v(
  "product_slug", "retailer_name", "affiliate_program",
  "destination_url", "regions", "currency", "price_label"
)
INNER JOIN "recommendation_products" p ON p."slug" = v."product_slug"
WHERE NOT EXISTS (
  SELECT 1
  FROM "recommendation_offers" o
  WHERE o."product_id" = p."id"
    AND o."retailer_name" = v."retailer_name"
);
